const required = ['project_name', 'country', 'technology_type', 'ownership_model', 'estimated_cost_usd'];
const missing = required.filter(field => !$json[field]);
if (missing.length > 0) throw new Error(`Missing required fields: ${missing.join(', ')}`);

const ownershipMap = { cooperative: 'community_cooperative', coop: 'community_cooperative', community: 'community_cooperative', public: 'public_utility', government: 'public_utility', hybrid: 'public_community_hybrid', private: 'private_ipp' };
const techMap = { 'mini-grid': 'solar_mini_grid', minigrid: 'solar_mini_grid', 'solar minigrid': 'solar_mini_grid', standalone: 'solar_standalone', shs: 'solar_home_systems' };
const rawOwnership = String($json.ownership_model || '').toLowerCase();
const rawTechnology = String($json.technology_type || '').toLowerCase();
const normalizedOwnership = ownershipMap[rawOwnership] || $json.ownership_model;
const normalizedTech = techMap[rawTechnology] || $json.technology_type;
if (normalizedOwnership === 'other' && !String($json.ownership_other || '').trim()) throw new Error('ownership_other is required when ownership_model is other');
if (normalizedTech === 'other' && !String($json.technology_other || '').trim()) throw new Error('technology_other is required when technology_type is other');

return [{ json: { project_intake: { project_name: $json.project_name, country: $json.country, location_description: $json.location_description || '', technology_type: normalizedTech, technology_other: normalizedTech === 'other' ? String($json.technology_other).trim() : null, capacity_kw: $json.capacity_kw || null, target_beneficiaries: $json.target_beneficiaries || '', ownership_model: normalizedOwnership, ownership_other: normalizedOwnership === 'other' ? String($json.ownership_other).trim() : null, productive_uses: $json.productive_uses || [], estimated_cost_usd: Number($json.estimated_cost_usd), existing_funding: $json.existing_funding || '', project_stage: $json.project_stage || 'concept', community_engagement: $json.community_engagement || '', additional_context: $json.additional_context || '', debt_preference: $json.debt_preference || 'grant_preferred' }, validation: { status: 'valid', timestamp: new Date().toISOString() } } }];

const intake = $json.project_intake;
const label = (value, custom) => value === 'other' && custom ? custom : String(value).replace(/_/g, ' ');
const ownershipLabel = label(intake.ownership_model, intake.ownership_other);
const technologyLabel = label(intake.technology_type, intake.technology_other);
const ownershipScores = { community_cooperative: 30, public_utility: 25, public_community_hybrid: 28, private_with_benefit_sharing: 10, private_ipp: 0, other: 5 };
let score = 50 + (ownershipScores[intake.ownership_model] || 0);
if (intake.productive_uses && intake.productive_uses.length > 0) score += 10;
if (intake.debt_preference === 'grant_only') score += 10;
else if (intake.debt_preference === 'grant_preferred') score += 5;
score = Math.min(score, 100);

// Project tier is based on financing preference, never ownership.
const debtTier = ['grant_only', 'grant_preferred'].includes(intake.debt_preference) ? 'tier_1' : 'tier_2';
const grantSuitable = ['Last-mile rural electrification focus'];
if (intake.ownership_model === 'community_cooperative') grantSuitable.push('Community cooperative ownership supports local benefit retention');
if (String(intake.ownership_model).includes('public')) grantSuitable.push('Public ownership supports public-interest infrastructure');
if (intake.productive_uses?.length) grantSuitable.push(`Productive use component: ${intake.productive_uses.join(', ')}`);
if (debtTier === 'tier_1') grantSuitable.push('Low/no-debt preference aligns with M300 debt sensitivity');

const debtRisks = [];
if (intake.ownership_model === 'private_ipp') debtRisks.push('Private IPP terms may include sovereign, tariff, or offtake guarantees');
if (intake.debt_preference === 'open_to_blended') debtRisks.push('Blended finance may introduce repayment, bridge-finance, currency, or guarantee exposure');
if (intake.debt_preference === 'any_instrument') debtRisks.push('Debt terms, obligor, currency, guarantees, and contingent liabilities require full review');
if (debtRisks.length === 0) debtRisks.push('No debt exposure identified from intake; verify current financing terms');
const privateRisks = ['Verify asset ownership, benefit-sharing, guarantees, and contingent liabilities for any private-capital structure'];
const alignmentLevel = score >= 70 ? 'strong' : score >= 50 ? 'moderate' : 'weak';
const narrative = `This ${technologyLabel} project in ${intake.country} demonstrates ${alignmentLevel} alignment with M300 principles (score: ${score}/100). The ${ownershipLabel} model is assessed separately from the project's ${debtTier === 'tier_1' ? 'low/no-debt preference' : 'willingness to consider some debt'}. Productive-use, governance, and financing terms still require verification.`;

return [{ json: { project_intake: intake, policy_interpretation: { project_name: intake.project_name, m300_alignment_score: score, alignment_narrative: narrative, ownership_classification: intake.ownership_model, grant_suitable_elements: grantSuitable, debt_exposure_risks: debtRisks, private_capital_risks: privateRisks, community_ownership_justification: `The ${ownershipLabel} structure can retain local benefits when governance, asset ownership, and revenue allocation are verified.`, assumptions_list: ['Project entity is legally registered', 'Land/site tenure is secured', 'Community engagement is documented', 'Demand and technical feasibility are verified'], recommended_framing: `Position as a locally accountable ${technologyLabel} project aligned with M300 access goals and explicit ${debtTier === 'tier_1' ? 'low/no-debt' : 'debt-management'} safeguards.`, debt_sensitivity_tier: debtTier } } }];

const intake = $json.project_intake;
const interpretation = $json.policy_interpretation;
const grants = [
  { id: 'geapp_minigrid', funder_name: 'Global Energy Alliance for People and Planet (GEAPP)', instrument_type: 'grant', priority_countries: ['Nigeria', 'Kenya', 'Ethiopia', 'DRC'], regions: ['Sub-Saharan Africa'], thematic_focus: ['mini_grids', 'productive_use', 'distributed_renewables'], min_usd: 150000, max_usd: 500000, debt_tier: 1, community_support: true },
  { id: 'amsf_rbf', funder_name: 'Africa Mini-Grid Support Facility (AMSF)', instrument_type: 'results_based_grant', priority_countries: [], regions: ['West Africa', 'East Africa', 'Southern Africa'], thematic_focus: ['mini_grids'], min_usd: 100000, max_usd: 1000000, debt_tier: 2, community_support: true },
  { id: 'gcf_sap', funder_name: 'Green Climate Fund - Simplified Approval Process', instrument_type: 'grant', priority_countries: [], regions: ['Africa', 'Asia', 'Latin America', 'Pacific'], thematic_focus: ['climate_mitigation', 'climate_adaptation', 'renewable_energy'], min_usd: 250000, max_usd: 10000000, debt_tier: 1, community_support: true },
  { id: 'gavi_cceop', funder_name: 'Gavi Cold Chain Equipment Optimization Platform (CCEOP)', instrument_type: 'grant', priority_countries: ['Nigeria', 'DRC', 'Ethiopia'], regions: ['Gavi-eligible countries'], thematic_focus: ['vaccine_cold_chain', 'health_facility_electrification'], min_usd: 50000, max_usd: 5000000, debt_tier: 1, community_support: true },
  { id: 'usadf', funder_name: 'US African Development Foundation', instrument_type: 'grant', priority_countries: [], regions: ['Sub-Saharan Africa'], thematic_focus: ['community_enterprise', 'productive_use', 'energy_access'], min_usd: 50000, max_usd: 250000, debt_tier: 1, community_support: true },
  { id: 'power_africa_health', funder_name: 'Power Africa Health Electrification Initiative', instrument_type: 'grant', priority_countries: ['Nigeria', 'Kenya', 'Tanzania', 'Uganda', 'Ethiopia'], regions: ['Sub-Saharan Africa'], thematic_focus: ['health_facility_electrification'], min_usd: 100000, max_usd: 2000000, debt_tier: 1, community_support: true }
];
const normalizeTier = value => Number(value) === 1 || value === 'tier_1' ? 'tier_1' : 'tier_2';
const tech = intake.technology_type === 'other' && intake.technology_other ? intake.technology_other : intake.technology_type;
function scoreGrant(grant) {
  let geo = grant.priority_countries.some(c => c.toLowerCase() === intake.country.toLowerCase()) ? 100 : grant.regions.some(r => r.toLowerCase().includes('africa')) ? 60 : 0;
  let thematic = grant.thematic_focus.some(t => tech.toLowerCase().includes(t.split('_')[0])) ? 100 : grant.thematic_focus.includes('energy_access') || grant.thematic_focus.includes('renewable_energy') ? 60 : 30;
  if (intake.productive_uses?.some(u => u.includes('cold_chain') || u.includes('medical')) && grant.thematic_focus.some(t => t.includes('health') || t.includes('vaccine'))) thematic = 100;
  const size = intake.estimated_cost_usd >= grant.min_usd && intake.estimated_cost_usd <= grant.max_usd ? 100 : intake.estimated_cost_usd >= grant.min_usd * 0.5 && intake.estimated_cost_usd <= grant.max_usd * 1.5 ? 60 : 30;
  const ownership = intake.ownership_model === 'community_cooperative' && grant.community_support ? 100 : String(intake.ownership_model).includes('public') || String(intake.ownership_model).includes('community') ? 80 : 40;
  const redFlags = [];
  if (size === 30) redFlags.push('Project cost outside typical funder range');
  if (intake.debt_preference === 'grant_only' && !['grant', 'results_based_grant'].includes(grant.instrument_type)) redFlags.push('Instrument may conflict with grant-only preference');
  if (grant.instrument_type === 'results_based_grant') redFlags.push('Results-based payment may require bridge financing');
  const tier = normalizeTier(grant.debt_tier);
  const base = geo * 0.25 + thematic * 0.30 + size * 0.15 + ownership * 0.20 + 70 * 0.10;
  const penalty = Math.min(redFlags.length * 0.10, 0.30);
  return { score: Math.round(base * (1 - penalty) * (tier === 'tier_1' ? 1 : 0.90)), redFlags, tier };
}
const scored = grants.map(grant => { const result = scoreGrant(grant); return { funder_id: grant.id, funder_name: grant.funder_name, instrument_type: grant.instrument_type, fit_score: result.score, debt_sensitivity_tier: result.tier, fit_rationale: [`Country/region assessed for ${intake.country}`, `Technology assessed as ${String(tech).replace(/_/g, ' ')}`, `Project cost assessed against $${grant.min_usd.toLocaleString()}–$${grant.max_usd.toLocaleString()}`, grant.community_support ? 'Community-oriented models supported' : 'Ownership terms require review'], red_flags: result.redFlags, next_actions: [`Verify ${grant.funder_name} opportunity and terms on an official source`, 'Prepare project documentation', 'Complete demand and financial assessments', 'Record debt, currency, guarantee, and bridge-finance terms'] }; });
const matches = scored.filter(item => item.fit_score >= 30).sort((a, b) => b.fit_score - a.fit_score).slice(0, 5);
const excluded = scored.filter(item => item.fit_score < 30).slice(0, 3).map(item => ({ funder_id: item.funder_id, funder_name: item.funder_name, exclusion_reason: `Fit score ${item.fit_score} below threshold 30` }));
const top = matches[0];
const strategy = top ? `Lead with ${top.funder_name} for verification (${top.fit_score}/100 provisional fit). Compare Tier 2 options rather than excluding them, and document all debt-related terms.` : 'No qualifying match; verify current sources and review project parameters.';
return [{ json: { project_intake: intake, policy_interpretation: interpretation, grant_match: { project_name: intake.project_name, matches, excluded_funders: excluded, overall_funding_strategy: strategy, debt_sensitivity_summary: { tier_1_count: matches.filter(m => m.debt_sensitivity_tier === 'tier_1').length, tier_2_count: matches.filter(m => m.debt_sensitivity_tier === 'tier_2').length, recommendation: 'Prefer Tier 1 where overall fit is comparable; retain Tier 2 with explicit due diligence.' }, matching_metadata: { total_funders_evaluated: grants.length, scoring_weights_version: '2.0', timestamp: new Date().toISOString() } } } }];

const intake = $json.project_intake;
const interpretation = $json.policy_interpretation;
const grantMatch = $json.grant_match;
const label = (value, custom) => value === 'other' && custom ? custom : String(value).replace(/_/g, ' ');
const ownership = label(intake.ownership_model, intake.ownership_other);
const technology = label(intake.technology_type, intake.technology_other);
const targetFunder = grantMatch.matches[0]?.funder_name || 'General';
const proposalOutline = { problem_statement: `People in ${intake.location_description || intake.country} lack reliable electricity. The ${technology} project should quantify affected people, current energy costs, and service impacts.`, theory_of_change: `IF ${intake.project_name} is implemented through the ${ownership} model, THEN ${intake.target_beneficiaries || 'target beneficiaries'} can gain electricity access, subject to verified technical, governance, and affordability assumptions.`, community_ownership_governance: `Document ownership, decision rights, benefit-sharing, tariff oversight, asset transfer, and accountability for the ${ownership} structure. ${interpretation.community_ownership_justification}`, technical_approach: `${intake.capacity_kw ? `${intake.capacity_kw}kW` : 'Appropriately sized'} ${technology} system; validate the load, reliability, maintainability, and productive-use assumptions.`, affordability_tariff_principles: 'Test ability to pay, operating cost recovery, lifeline protection, revenue allocation, and transparent tariff review.', implementation_plan: 'Phase 1: verification and design; Phase 2: procurement and site preparation; Phase 3: installation and commissioning; Phase 4: connections, training, monitoring, and learning.', mel_framework: 'Track verified outputs, service reliability, affordability, productive-use outcomes, beneficiary feedback, and governance performance.', risk_register: `Technical, financial, governance, and delivery assumptions require evidence. DEBT SENSITIVITY (${interpretation.debt_sensitivity_tier}): ${interpretation.debt_exposure_risks.join('. ')} Tier 2 remains eligible but requires repayment, currency, obligor, guarantee, and contingent-liability review.` };
const readinessChecklist = [
  { item: 'Legal entity registration', status: 'unknown', notes: 'Verify current registration evidence', priority: 'critical' },
  { item: 'Land/site documentation', status: 'unknown', notes: 'Verify tenure and site control', priority: 'critical' },
  { item: 'Community/stakeholder endorsement', status: 'unknown', notes: 'Document support and consultation', priority: 'critical' },
  { item: 'Demand assessment', status: 'not_ready', notes: 'Complete with traceable evidence', priority: 'critical' },
  { item: 'Technical feasibility/design', status: 'not_ready', notes: 'Commission qualified review', priority: 'important' },
  { item: 'Budget and financing terms', status: 'not_ready', notes: 'Record quotes, debt, currency, guarantees, and contingencies', priority: 'important' },
  { item: 'Financial projections', status: 'not_ready', notes: 'Test affordability and debt service where applicable', priority: 'important' }
];
const missingInfo = ['What is the exact project location?', `What is the registration and governance status of the ${ownership} entity?`, 'What evidence supports demand and ability-to-pay assumptions?', 'What funding components, currencies, guarantees, and contingent liabilities are proposed?', 'Which current official source confirms the funder opportunity and terms?', 'What technical and financial studies have been completed?'];
return [{ json: { project_intake: intake, policy_interpretation: interpretation, grant_match: grantMatch, proposal_coach: { project_name: intake.project_name, target_funder: targetFunder, proposal_outline: proposalOutline, readiness_checklist: readinessChecklist, missing_info_questionnaire: missingInfo } } }];
